278	/* byte string */
279	struct UnsizedByteStr : UnsizedArrayOf <HBUINT8>
280	{
281	  // encode 2-byte int (Dict/CharString) or 4-byte int (Dict)
282	  template <typename INTTYPE, int minVal, int maxVal>
283	  inline static bool serialize_int (hb_serialize_context_t *c, OpCode intOp, int value)
284	  {
285	    TRACE_SERIALIZE (this);
286	
287	    if (unlikely ((value < minVal || value > maxVal)))
288	      return_trace (false);
289	
290	    HBUINT8 *p = c->allocate_size<HBUINT8> (1);
291	    if (unlikely (p == nullptr)) return_trace (false);
292	    p->set (intOp);
293	
294	    INTTYPE *ip = c->allocate_size<INTTYPE> (INTTYPE::static_size);
295	    if (unlikely (ip == nullptr)) return_trace (false);
296	    ip->set ((unsigned int)value);
297	
298	    return_trace (true);
299	  }
300	
301	  inline static bool serialize_int4 (hb_serialize_context_t *c, int value)
302	  { return serialize_int<HBUINT32, 0, 0x7FFFFFFF> (c, OpCode_longintdict, value); }
303	
304	  inline static bool serialize_int2 (hb_serialize_context_t *c, int value)
305	  { return serialize_int<HBUINT16, 0, 0x7FFF> (c, OpCode_shortint, value); }
306	
307	  /* Defining null_size allows a Null object may be created. Should be safe because:
308	   * A descendent struct Dict uses a Null pointer to indicate a missing table,
309	   * checked before access.
310	   * ByteStr, a wrapper struct pairing a byte pointer along with its length, always
311	   * checks the length before access. A Null pointer is used as the initial pointer
312	   * along with zero length by the default ctor.
313	   */
314	  DEFINE_SIZE_MIN(0);
315	};
316	
317	struct ByteStr
318	{
319	  inline ByteStr (void)
320	    : str (&Null(UnsizedByteStr)), len (0) {}
321	  inline ByteStr (const UnsizedByteStr& s, unsigned int l)
322	    : str (&s), len (l) {}
323	  inline ByteStr (const char *s, unsigned int l=0)
324	    : str ((const UnsizedByteStr *)s), len (l) {}
325	  /* sub-string */
326	  inline ByteStr (const ByteStr &bs, unsigned int offset, unsigned int len_)
327	  {
328	    str = (const UnsizedByteStr *)&bs.str[offset];
329	    len = len_;
330	  }
331	
332	  inline bool sanitize (hb_sanitize_context_t *c) const { return str->sanitize (c, len); }
333	
334	  inline const HBUINT8& operator [] (unsigned int i) const {
335	    if (likely (str && (i < len)))
336	      return (*str)[i];
337	    else
338	      return Null(HBUINT8);
339	  }
340	
341	  inline bool serialize (hb_serialize_context_t *c, const ByteStr &src)
342	  {
343	    TRACE_SERIALIZE (this);
344	    HBUINT8 *dest = c->allocate_size<HBUINT8> (src.len);
345	    if (unlikely (dest == nullptr))
346	      return_trace (false);
347	    memcpy (dest, src.str, src.len);
348	    return_trace (true);
349	  }
350	
351	  inline unsigned int get_size (void) const { return len; }
352	
353	  inline bool check_limit (unsigned int offset, unsigned int count) const
354	  { return (offset + count <= len); }
355	
356	  const UnsizedByteStr *str;
357	  unsigned int len;
358	};
