360	struct SubByteStr
361	{
362	  inline SubByteStr (void)
363	  { init (); }
364	
365	  inline void init (void)
366	  {
367	    str = ByteStr (0);
368	    offset = 0;
369	    error = false;
370	  }
371	
372	  inline void fini (void) {}
373	
374	  inline SubByteStr (const ByteStr &str_, unsigned int offset_ = 0)
375	    : str (str_), offset (offset_), error (false) {}
376	
377	  inline void reset (const ByteStr &str_, unsigned int offset_ = 0)
378	  {
379	    str = str_;
380	    offset = offset_;
381	    error = false;
382	  }
383	
384	  inline const HBUINT8& operator [] (int i) {
385	    if (unlikely ((unsigned int)(offset + i) >= str.len))
386	    {
387	      set_error ();
388	      return Null(HBUINT8);
389	    }
390	    else
391	      return str[offset + i];
392	  }
393	
394	  inline operator ByteStr (void) const { return ByteStr (str, offset, str.len - offset); }
395	
396	  inline bool avail (unsigned int count=1) const
397	  {
398	    return (!in_error () && str.check_limit (offset, count));
399	  }
400	  inline void inc (unsigned int count=1)
401	  {
402	    if (likely (!in_error () && (offset <= str.len) && (offset + count <= str.len)))
403	    {
404	      offset += count;
405	    }
406	    else
407	    {
408	      offset = str.len;
409	      set_error ();
410	    }
411	  }
412	
413	  inline void set_error (void) { error = true; }
414	  inline bool in_error (void) const { return error; }
415	
416	  ByteStr       str;
417	  unsigned int  offset; /* beginning of the sub-string within str */
418	
419	  protected:
420	  bool	  error;
421	};
