425	/* stack */
426	template <typename ELEM, int LIMIT>
427	struct Stack
428	{
429	  inline void init (void)
430	  {
431	    error = false;
432	    count = 0;
433	    elements.init ();
434	    elements.resize (kSizeLimit);
435	    for (unsigned int i = 0; i < elements.len; i++)
436	      elements[i].init ();
437	  }
438	
439	  inline void fini (void)
440	  {
441	    elements.fini_deep ();
442	  }
443	
444	  inline ELEM& operator [] (unsigned int i)
445	  {
446	    if (unlikely (i >= count)) set_error ();
447	    return elements[i];
448	  }
449	
450	  inline void push (const ELEM &v)
451	  {
452	    if (likely (count < elements.len))
453	      elements[count++] = v;
454	    else
455	      set_error ();
456	  }
457	
458	  inline ELEM &push (void)
459	  {
460	    if (likely (count < elements.len))
461	      return elements[count++];
462	    else
463	    {
464	      set_error ();
465	      return Crap(ELEM);
466	    }
467	  }
468	
469	  inline ELEM& pop (void)
470	  {
471	    if (likely (count > 0))
472	      return elements[--count];
473	    else
474	    {
475	      set_error ();
476	      return Crap(ELEM);
477	    }
478	  }
479	
480	  inline void pop (unsigned int n)
481	  {
482	    if (likely (count >= n))
483	      count -= n;
484	    else
485	      set_error ();
486	  }
487	
488	  inline const ELEM& peek (void)
489	  {
490	    if (likely (count > 0))
491	      return elements[count-1];
492	    else
493	    {
494	      set_error ();
495	      return Null(ELEM);
496	    }
497	  }
498	
499	  inline void unpop (void)
500	  {
501	    if (likely (count < elements.len))
502	      count++;
503	    else
504	      set_error ();
505	  }
506	
507	  inline void clear (void) { count = 0; }
508	
509	  inline bool in_error (void) const { return (error || elements.in_error ()); }
510	  inline void set_error (void) { error = true; }
511	
512	  inline unsigned int get_count (void) const { return count; }
513	  inline bool is_empty (void) const { return count == 0; }
514	
515	  static const unsigned int kSizeLimit = LIMIT;
516	
517	  protected:
518	  bool error;
519	  unsigned int count;
520	  hb_vector_t<ELEM, kSizeLimit> elements;
521	};
522	
523	/* argument stack */
524	template <typename ARG=Number>
525	struct ArgStack : Stack<ARG, 513>
526	{
527	  inline void push_int (int v)
528	  {
529	    ARG &n = S::push ();
530	    n.set_int (v);
531	  }
532	
533	  inline void push_fixed (int32_t v)
534	  {
535	    ARG &n = S::push ();
536	    n.set_fixed (v);
537	  }
538	
539	  inline void push_real (double v)
540	  {
541	    ARG &n = S::push ();
542	    n.set_real (v);
543	  }
544	
545	  inline ARG& pop_num (void)
546	  {
547	    return this->pop ();
548	  }
549	
550	  inline int pop_int (void)
551	  {
552	    return this->pop ().to_int ();
553	  }
554	
555	  inline unsigned int pop_uint (void)
556	  {
557	    int  i = pop_int ();
558	    if (unlikely (i < 0))
559	    {
560	      i = 0;
561	      S::set_error ();
562	    }
563	    return (unsigned)i;
564	  }
565	
566	  inline void push_longint_from_substr (SubByteStr& substr)
567	  {
568	    push_int ((substr[0] << 24) | (substr[1] << 16) | (substr[2] << 8) | (substr[3]));
569	    substr.inc (4);
570	  }
571	
572	  inline bool push_fixed_from_substr (SubByteStr& substr)
573	  {
574	    if (unlikely (!substr.avail (4)))
575	      return false;
576	    push_fixed ((int32_t)*(const HBUINT32*)&substr[0]);
577	    substr.inc (4);
578	    return true;
579	  }
580	
581	  inline hb_array_t<const ARG> get_subarray (unsigned int start) const
582	  {
583	    return S::elements.sub_array (start);
584	  }
585	
586	  private:
587	  typedef Stack<ARG, 513> S;
588	};
589	
590	/* an operator prefixed by its operands in a byte string */
591	struct OpStr
592	{
593	  inline void init (void) {}
594	  inline void fini (void) {}
595	
596	  OpCode  op;
597	  ByteStr str;
598	};
599	
600	/* base of OP_SERIALIZER */
601	struct OpSerializer
602	{
603	  protected:
604	  inline bool copy_opstr (hb_serialize_context_t *c, const OpStr& opstr) const
605	  {
606	    TRACE_SERIALIZE (this);
607	
608	    HBUINT8 *d = c->allocate_size<HBUINT8> (opstr.str.len);
609	    if (unlikely (d == nullptr)) return_trace (false);
610	    memcpy (d, &opstr.str.str[0], opstr.str.len);
611	    return_trace (true);
612	  }
613	};
614	
615	template <typename VAL>
616	struct ParsedValues
617	{
618	  inline void init (void)
619	  {
620	    opStart = 0;
621	    values.init ();
622	  }
623	
624	  inline void fini (void)
625	  {
626	    values.fini_deep ();
627	  }
628	
629	  inline void add_op (OpCode op, const SubByteStr& substr = SubByteStr ())
630	  {
631	    VAL *val = values.push ();
632	    val->op = op;
633	    val->str = ByteStr (substr.str, opStart, substr.offset - opStart);
634	    opStart = substr.offset;
635	  }
636	
637	  inline void add_op (OpCode op, const SubByteStr& substr, const VAL &v)
638	  {
639	    VAL *val = values.push (v);
640	    val->op = op;
641	    val->str = ByteStr (substr.str, opStart, substr.offset - opStart);
642	    opStart = substr.offset;
643	  }
644	
645	  inline bool has_op (OpCode op) const
646	  {
647	    for (unsigned int i = 0; i < get_count (); i++)
648	      if (get_value (i).op == op) return true;
649	    return false;
650	  }
651	
652	  inline unsigned get_count (void) const { return values.len; }
653	  inline const VAL &get_value (unsigned int i) const { return values[i]; }
654	  inline const VAL &operator [] (unsigned int i) const { return get_value (i); }
655	
656	  unsigned int       opStart;
657	  hb_vector_t<VAL>   values;
658	};
659	
660	template <typename ARG=Number>
661	struct InterpEnv
662	{
663	  inline void init (const ByteStr &str_)
664	  {
665	    substr.reset (str_);
666	    argStack.init ();
667	    error = false;
668	  }
669	
670	  inline void fini (void)
671	  {
672	    argStack.fini ();
673	  }
674	
675	  inline bool in_error (void) const
676	  {
677	    return error || substr.in_error () || argStack.in_error ();
678	  }
679	
680	  inline void set_error (void) { error = true; }
681	
682	  inline OpCode fetch_op (void)
683	  {
684	    OpCode  op = OpCode_Invalid;
685	    if (unlikely (!substr.avail ()))
686	      return OpCode_Invalid;
687	    op = (OpCode)(unsigned char)substr[0];
688	    if (op == OpCode_escape) {
689	      if (unlikely (!substr.avail ()))
690		return OpCode_Invalid;
691	      op = Make_OpCode_ESC(substr[1]);
692	      substr.inc ();
693	    }
694	    substr.inc ();
695	    return op;
696	  }
697	
698	  inline const ARG& eval_arg (unsigned int i)
699	  {
700	    return argStack[i];
701	  }
702	
703	  inline ARG& pop_arg (void)
704	  {
705	    return argStack.pop ();
706	  }
707	
708	  inline void pop_n_args (unsigned int n)
709	  {
710	    argStack.pop (n);
711	  }
712	
713	  inline void clear_args (void)
714	  {
715	    pop_n_args (argStack.get_count ());
716	  }
717	
718	  SubByteStr    substr;
719	  ArgStack<ARG> argStack;
720	  protected:
721	  bool	  error;
722	};
723	
724	typedef InterpEnv<> NumInterpEnv;
725	
726	template <typename ARG=Number>
727	struct OpSet
728	{
729	  static inline void process_op (OpCode op, InterpEnv<ARG>& env)
730	  {
731	    switch (op) {
732	      case OpCode_shortint:
733		env.argStack.push_int ((int16_t)((env.substr[0] << 8) | env.substr[1]));
734		env.substr.inc (2);
735		break;
736	
737	      case OpCode_TwoBytePosInt0: case OpCode_TwoBytePosInt1:
738	      case OpCode_TwoBytePosInt2: case OpCode_TwoBytePosInt3:
739		env.argStack.push_int ((int16_t)((op - OpCode_TwoBytePosInt0) * 256 + env.substr[0] + 108));
740		env.substr.inc ();
741		break;
742	
743	      case OpCode_TwoByteNegInt0: case OpCode_TwoByteNegInt1:
744	      case OpCode_TwoByteNegInt2: case OpCode_TwoByteNegInt3:
745		env.argStack.push_int ((int16_t)(-(op - OpCode_TwoByteNegInt0) * 256 - env.substr[0] - 108));
746		env.substr.inc ();
747		break;
748	
749	      default:
750		/* 1-byte integer */
751		if (likely ((OpCode_OneByteIntFirst <= op) && (op <= OpCode_OneByteIntLast)))
752		{
753		  env.argStack.push_int ((int)op - 139);
754		} else {
755		  /* invalid unknown operator */
756		  env.clear_args ();
757		  env.set_error ();
758		}
759		break;
760	    }
761	  }
762	};
763	
764	template <typename ENV>
765	struct Interpreter {
766	
767	  inline ~Interpreter(void) { fini (); }
768	
769	  inline void fini (void) { env.fini (); }
770	
771	  ENV env;
772	};
773	
774	} /* namespace CFF */
775	
776	#endif /* HB_CFF_INTERP_COMMON_HH */
